/**
 * Clinically significant medication base catalog for Assessment.
 * Evidence-informed primary and common off-label uses (educational).
 * Expanded to 100,000 catalog entries via strength × route × formulation editions.
 * Not a prescribing system — users record what their clinicians prescribed.
 * Generated by scripts/gen-medications.mjs — edit the script to regenerate.
 */

import type { MedicationBase, MedicationClass, MedicationRoute } from "./medications-types";

function m(p: {
  slug: string;
  genericName: string;
  brandNames: string[];
  classId: MedicationClass;
  primaryUse: string;
  offLabelUses: string[];
  routes: MedicationRoute[];
  strengths: string[];
  evidenceNote: string;
  ptRelevantNotes?: string;
  controlledSchedule?: MedicationBase["controlledSchedule"];
}): MedicationBase {
  const searchTerms = Array.from(
    new Set(
      [
        p.genericName,
        p.slug.replace(/-/g, " "),
        ...p.brandNames,
        p.primaryUse,
        ...p.offLabelUses,
        ...p.strengths,
        ...p.routes,
        p.classId.replace(/-/g, " "),
      ]
        .join(" ")
        .toLowerCase()
        .split(/[^a-z0-9+.\/]+/)
        .filter((t) => t.length > 1)
    )
  );
  return {
    id: `med-${p.slug}`,
    slug: p.slug,
    genericName: p.genericName,
    brandNames: p.brandNames,
    classId: p.classId,
    primaryUse: p.primaryUse,
    offLabelUses: p.offLabelUses,
    routes: p.routes,
    defaultRoute: p.routes[0]!,
    commonStrengths: p.strengths,
    evidenceNote: p.evidenceNote,
    ptRelevantNotes: p.ptRelevantNotes,
    controlledSchedule: p.controlledSchedule ?? "none",
    searchTerms,
  };
}

